// GarageTexBlob.swift - CC0 photo-textures for garage floor and walls.
// Floor: ambientCG Concrete034 (CC0, https://ambientcg.com/view?id=Concrete034).
// Walls: Poly Haven concrete_block_wall (CC0, https://polyhaven.com/a/concrete_block_wall),
// tone-adjusted (brightened, desaturated) to painted-cinderblock light/dark wall bases.
// No procedural noise added. See ASSETS.md.
// Payloads are single-line string literals: multiline """ blocks inject newlines
// that break Data(base64Encoded:), and long "+" literal chains blow up the build.
import Foundation
import UIKit

enum GarageTexBlob {
    private static func img(_ b64: String) -> UIImage {
        guard let data = Data(base64Encoded: b64, options: [.ignoreUnknownCharacters]),
              let image = UIImage(data: data) else {
            // Loud failure: a magenta surface cannot be mistaken for a real
            // texture in screenshots, and the log line names the regression.
            NSLog("[GARAGETEX] texture decode FAILED - using magenta fallback")
            let renderer = UIGraphicsImageRenderer(size: CGSize(width: 4, height: 4))
            return renderer.image { ctx in
                UIColor.magenta.setFill()
                ctx.fill(CGRect(x: 0, y: 0, width: 4, height: 4))
            }
        }
        return image
    }

    static let floor: UIImage = { img(floorB64) }()
    static let wallNorth: UIImage = { img(wallNB64) }()
    static let wallDark: UIImage = { img(wallDB64) }()

    // MARK: - Base64 payloads (one literal per texture, no newlines, no concat)
    private static let floorB64 = ""
    private static let wallNB64 = ""
    private static let wallDB64 = ""
}
